import cuda.bindings.driver as cuda
import cutlass
import cutlass.cute as cute
from cutlass import Int32

from lumen.codegen.elementwise.cuda.kernel import ElementwiseKernel


@cute.jit
def BODY(ins, outs, fins, fouts, j, v, SEGMENT: cutlass.Constexpr):
    """Every output of segment `SEGMENT` at flat index `j`, the tensors read and written at `j` through
    `fins` and `fouts` at `v`."""
    in0 = ins[0]
    in1 = ins[1]
    out0 = outs[0]
    fin0 = fins[0]
    fin1 = fins[1]
    fout0 = fouts[0]
    if cutlass.const_expr(SEGMENT == 0):
        v0 = fin0[v]
        v1 = fin1[v]
        t2 = (v1 >= 0) & (v1 < 32)
        t3 = cutlass.Int32(cutlass.select_(t2, v1, cutlass.Int32(0)))
        v4 = cutlass.select_(t2, v0 << t3, cutlass.Int32(0))
        fout0[v] = v4


@cute.jit
def launch(in0, in1, out0, blocks: Int32, stream: cuda.CUstream, vectorized: cutlass.Constexpr):
    """Runs the fusion's `ElementwiseKernel` on `blocks` blocks on `stream`, with vector loads and stores
    when `vectorized` (every tensor 16-byte aligned)."""
    kernel = ElementwiseKernel(BODY, (1048576, ), (cutlass.Int32, cutlass.Int32, cutlass.Int32, ), (1048576, 1048576, 1048576, ), ((0, 1, ), ), ((0, ), ), (True, ), vectorized)
    kernel.launch([in0, in1], [out0], blocks, stream)
